[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][string]$ProjectPath,
 [string]$PilotPlanPath='Research\Gate13R_36h_10pct_4Lane_Pilot_Plan.v10.json',
 [string]$SchedulePath='Research\Gate13R_36h_10pct_4Lane_Pilot_Schedule.v10.json',
 [string]$ProvenancePath='Research\Gate13R_36h_10pct_4Lane_Provenance.v10.json',
 [Parameter(Mandatory=$true)][string]$PrePilotAuditPath,
 [string]$UnityPath='H:\UnityEditor\2022.3.30f1c1\Editor\Unity.exe',
 [switch]$BindingSmokeOnly,
 [int]$BlockTimeoutSeconds=3600,
 [int]$WaveTimeoutSeconds=4200
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);if(-not[IO.Path]::IsPathRooted($PilotPlanPath)){$PilotPlanPath=Join-Path $ProjectPath $PilotPlanPath};if(-not[IO.Path]::IsPathRooted($SchedulePath)){$SchedulePath=Join-Path $ProjectPath $SchedulePath};if(-not[IO.Path]::IsPathRooted($ProvenancePath)){$ProvenancePath=Join-Path $ProjectPath $ProvenancePath};$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$SchedulePath=[IO.Path]::GetFullPath($SchedulePath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$PrePilotAuditPath=[IO.Path]::GetFullPath($PrePilotAuditPath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13R36hConcurrencyPilotV10|$ProjectPath");exit 0}
Import-Module (Join-Path $ProjectPath 'Research\Gate13R36hConcurrencyPreparationV10.psm1') -Force
$plan=Read-G13R36Json $PilotPlanPath;$scheduleDoc=Read-G13R36Json $SchedulePath;$provenance=Read-G13R36Json $ProvenancePath;$preAudit=Read-G13R36Json $PrePilotAuditPath
if([string]$plan.planId-ne'gate13r-36h-10pct-four-lane-nonformal-pilot-plan-v10'-or$plan.formalCampaign-ne$false){throw 'Pilot plan identity/boundary mismatch.'};if([string]$scheduleDoc.planId-ne[string]$plan.planId-or$scheduleDoc.formalCampaign-ne$false-or@($scheduleDoc.rows).Count-ne384){throw 'Pilot schedule identity/cardinality mismatch.'};if([string]$provenance.executionDesignId-ne[string]$plan.executionDesignId-or$provenance.formalCampaign-ne$false){throw 'Provenance identity/boundary mismatch.'};if($preAudit.passed-ne$true-or$preAudit.pilotRootCreated-ne$false){throw 'A passing validation-only pre-pilot audit is required.'}
foreach($binding in @(@($PilotPlanPath,[string]$provenance.config.sha256),@($SchedulePath,[string]$provenance.schedule.sha256))){if((Get-G13R36LowerSha256 $binding[0])-ne$binding[1]){throw "Bound hash mismatch: $($binding[0])"}}
$actualProvenanceSha=Get-G13R36LowerSha256 $ProvenancePath;$actualPlanSha=Get-G13R36LowerSha256 $PilotPlanPath;$actualScheduleSha=Get-G13R36LowerSha256 $SchedulePath
if([string]$preAudit.provenanceSha256-ne$actualProvenanceSha-or[string]$preAudit.pilotPlanSha256-ne$actualPlanSha-or[string]$preAudit.scheduleSha256-ne$actualScheduleSha){throw 'Pre-pilot audit is not bound to the active provenance, plan, and schedule.'}
$pilotRoot=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\')));$expectedPilot=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_36h_10pct_4Lane\v10'));if($pilotRoot-ne$expectedPilot){throw 'Pilot root differs from frozen path.'};if(Test-Path $pilotRoot){throw 'The sole pilot root already exists; retry/resume is forbidden.'}
$formalRoots=@((Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_ProcessReuse_5pct\v1'),(Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1'));foreach($root in $formalRoots){if(Test-Path $root){throw "Forbidden formal root exists: $root"}}
$laneRecords=@($plan.lanes);if($laneRecords.Count-ne4){throw 'Exactly four lanes are required.'};foreach($lane in $laneRecords){$root=[IO.Path]::GetFullPath([string]$lane.projectPath);if(-not(Test-Path $root -PathType Container)){throw "Lane project missing: $root"};if(Test-Path (Join-Path $root 'Temp\UnityLockfile')){throw "Lane lock exists: $root"}}
if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count){throw 'Unity must be closed before pilot preflight.'}
$os=Get-CimInstance Win32_OperatingSystem;$freePhysical=[long]$os.FreePhysicalMemory*1024L;if($freePhysical-lt[long]$plan.environment.minimumFreePhysicalMemoryBytes){throw "Insufficient free physical memory: $freePhysical"}
$cpuSamples=New-Object Collections.Generic.List[double];for($i=0;$i-lt[int]$plan.environment.cpuLoadSampleCount;$i++){$values=@(Get-CimInstance Win32_Processor|ForEach-Object{[double]$_.LoadPercentage});$cpuSamples.Add([double](($values|Measure-Object -Average).Average));if($i-lt[int]$plan.environment.cpuLoadSampleCount-1){Start-Sleep -Seconds ([int]$plan.environment.cpuLoadSampleIntervalSeconds)}};$meanCpu=[double](($cpuSamples|Measure-Object -Average).Average);if($meanCpu-gt[double]$plan.environment.maximumMeanCpuLoadPercent){throw "Mean preflight CPU load $meanCpu exceeds threshold."}
$drive=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='H:'";$freeDrive=[long]$drive.FreeSpace;if($freeDrive-lt[long]$plan.environment.minimumSourceDriveFreeBytes-or$freeDrive-lt[long]$plan.storageFeasibility.freeSpaceReserveBytes){throw "Insufficient H: free bytes: $freeDrive"}
$activePower=(&powercfg.exe /GETACTIVESCHEME 2>&1|Out-String);if($activePower.ToLowerInvariant()-notlike('*'+([string]$plan.environment.requiredPowerSchemeGuid).ToLowerInvariant()+'*')){throw "Active power scheme differs from frozen GUID: $activePower"}
$batteries=@(Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue);$acPassed=$true;foreach($battery in $batteries){if([int]$battery.BatteryStatus-in@(1,4,5)){$acPassed=$false}};if(-not$acPassed){throw 'Battery telemetry indicates non-AC/discharging state.'}
$preflight=[ordered]@{schemaVersion=1;kind='gate13r-36h-four-lane-pilot-launch-preflight-v1';capturedAtUtc=[DateTime]::UtcNow.ToString('o');freePhysicalMemoryBytes=$freePhysical;minimumFreePhysicalMemoryBytes=[long]$plan.environment.minimumFreePhysicalMemoryBytes;cpuLoadSamples=$cpuSamples.ToArray();meanCpuLoadPercent=$meanCpu;maximumMeanCpuLoadPercent=[double]$plan.environment.maximumMeanCpuLoadPercent;drive='H:';freeDriveBytes=$freeDrive;activePowerSchemeText=$activePower.Trim();batteryCount=$batteries.Count;acPassed=$acPassed;unityProcessCount=0;laneLocksAbsent=$true;formalRootsAbsent=$true;passed=$true}
New-Item -ItemType Directory -Path $pilotRoot -Force|Out-Null;Write-G13R36CreateNewUtf8NoBomJson -Path (Join-Path $pilotRoot 'launch-preflight.json') -Value $preflight -Depth 20
$receipt=[ordered]@{schemaVersion=1;receiptKind='gate13r-36h-four-lane-nonformal-pilot-execution-receipt-v10';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='NON-FORMAL / EXCLUDED-FROM-FORMAL-ANALYSIS';tokens=@('NON-FORMAL','EXCLUDED-FROM-FORMAL-ANALYSIS','NO-AUTO-RETRY','NO-RESUME','NO-PARTIAL-MERGE','FORMAL-CAMPAIGN-NOT-AUTHORIZED');planSha256=Get-G13R36LowerSha256 $PilotPlanPath;scheduleSha256=Get-G13R36LowerSha256 $SchedulePath;provenanceSha256=Get-G13R36LowerSha256 $ProvenancePath;prePilotAuditSha256=Get-G13R36LowerSha256 $PrePilotAuditPath;pilotRoot=$pilotRoot;laneCount=4;measuredBlockCount=384;formalCampaign=$false;formalExecutionAuthorized=$false};Write-G13R36CreateNewUtf8NoBomJson -Path (Join-Path $pilotRoot 'execution-receipt.json') -Value $receipt -Depth 20
$windowsPowerShell='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';$blockRunner=Join-Path $ProjectPath 'Research\Run-Gate13R36hBlockV10.ps1';$campaigns=@(Get-G13R36PilotCampaigns -ProjectPath $ProjectPath -Plan $plan);$campaignMap=@{};foreach($c in $campaigns){$campaignMap[[string]$c.campaignId]=$c};$checkpointPath=Join-Path $pilotRoot 'pilot-checkpoint.json';$ledger=New-Object Collections.Generic.List[object];$completedMeasured=0;$completedWarmup=0;$measuredStarted=$null;$measuredCompleted=$null
function Assert-Quiescent {if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count){throw 'Unexpected Unity process at wave boundary.'};foreach($lane in $laneRecords){if(Test-Path (Join-Path ([string]$lane.projectPath) 'Temp\UnityLockfile')){throw "Lane lock at wave boundary: $($lane.lane)"}}}
function Write-Checkpoint([string]$Status,[int]$CurrentWave,[string]$ErrorText){$value=[ordered]@{schemaVersion=1;checkpointKind='gate13r-36h-four-lane-nonformal-pilot-checkpoint-v10';savedAtUtc=[DateTime]::UtcNow.ToString('o');status=$Status;currentWave=$CurrentWave;completedWarmupBlocks=$completedWarmup;completedMeasuredBlocks=$completedMeasured;expectedMeasuredBlocks=384;ledger=$ledger.ToArray();error=$ErrorText;automaticRetryAuthorized=$false;automaticResumeAuthorized=$false;formalCampaign=$false};Write-G13R36AtomicUtf8NoBomJson -Path $checkpointPath -Value $value -Depth 30}
function New-JobPlan($Campaign,[int]$Block,[int]$Lane,[string]$Role,[string]$PlanPath){$laneRoot=[IO.Path]::GetFullPath([string]$laneRecords[$Lane-1].projectPath);$laneProvenance=Join-Path $laneRoot 'Research\Gate13R_36h_10pct_4Lane_Provenance.v10.json';$probe=Join-Path $laneRoot 'Research\Verification\Gate13R_36h_10pct_4Lane\v10\TelemetryProbe\telemetry-probe-result.json';$object=New-G13R36BlockPlan -LaneProjectPath $laneRoot -Plan $plan -Provenance $provenance -Campaign $Campaign -Block $Block -LaneProvenancePath $laneProvenance -LaneTelemetryProbeResultPath $probe -AnalysisRole $Role;Write-G13R36Utf8NoBomJson -Path $PlanPath -Value $object -Depth 30;return $object}
function Invoke-Wave([int]$Wave,$Items,[string]$Phase){Assert-Quiescent;$processes=New-Object Collections.Generic.List[object];$waveStarted=[DateTimeOffset]::Now
 foreach($item in @($Items)){$lane=[int]$item.lane;$laneRecord=$laneRecords[$lane-1];$campaign=$campaignMap[[string]$item.campaignId];$planDir=Join-Path $pilotRoot ('_plans\{0}\wave-{1:D3}'-f$Phase,$Wave);New-Item -ItemType Directory -Path $planDir -Force|Out-Null;$blockPlanPath=Join-Path $planDir ('lane-{0:D2}.block-plan.json'-f$lane);$role=if($Phase-eq'warmup'){'excluded-warmup'}else{'measured-non-formal-pilot'};$blockPlan=New-JobPlan $campaign ([int]$item.block) $lane $role $blockPlanPath;$output=Join-Path $pilotRoot ('{0}\wave-{1:D3}\lane-{2:D2}-{3}'-f$Phase,$Wave,$lane,[string]$blockPlan.blockId);$stdout=$output+'.wrapper.stdout.log';$stderr=$output+'.wrapper.stderr.log';$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$blockRunner,'-BlockPlanPath',$blockPlanPath,'-OutputDirectory',$output,'-AllowedRoot',$pilotRoot,'-Mode','Pilot','-SourceProjectPath',$ProjectPath,'-LaneProjectPath',[string]$laneRecord.projectPath,'-LaneNumber',[string]$lane,'-AffinityMaskHex',[string]$laneRecord.affinityMaskHex,'-UnityPath',$UnityPath,'-TimeoutSeconds',[string]$BlockTimeoutSeconds);$wp=Start-Process -FilePath $windowsPowerShell -ArgumentList $args -WorkingDirectory $ProjectPath -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$processes.Add([pscustomobject]@{lane=$lane;wrapper=$wp;blockId=[string]$blockPlan.blockId;campaignId=[string]$item.campaignId;block=[int]$item.block;output=$output;stdout=$stdout;stderr=$stderr})}
 $deadline=(Get-Date).AddSeconds($WaveTimeoutSeconds);do{$alive=@($processes|Where-Object{-not$_.wrapper.HasExited});if($alive.Count-eq0){break};if((Get-Date)-ge$deadline){foreach($owned in $alive){&taskkill.exe /PID $owned.wrapper.Id /T /F 2>&1|Out-Null};throw "Wave $Wave exceeded hard timeout $WaveTimeoutSeconds seconds."};Start-Sleep -Seconds 2;foreach($owned in $alive){$owned.wrapper.Refresh()}}while($true)
 $failed=New-Object Collections.Generic.List[string];foreach($owned in $processes){$owned.wrapper.Refresh();$exit=[int]$owned.wrapper.ExitCode;$summaryPath=$owned.output+'.wrapper-summary.json';if($exit-ne0-or-not(Test-Path $summaryPath)){$failed.Add("lane=$($owned.lane) block=$($owned.blockId) exit=$exit")}else{$summary=Read-G13R36Json $summaryPath;if($summary.passed-ne$true){$failed.Add("lane=$($owned.lane) block=$($owned.blockId) wrapper-summary-failed")}}};Assert-Quiescent;$waveCompleted=[DateTimeOffset]::Now;$entry=[pscustomobject][ordered]@{phase=$Phase;wave=$Wave;startedAt=$waveStarted.ToString('o');completedAt=$waveCompleted.ToString('o');wallSeconds=($waveCompleted-$waveStarted).TotalSeconds;blocks=@($processes|ForEach-Object{[pscustomobject]@{lane=$_.lane;campaignId=$_.campaignId;block=$_.block;blockId=$_.blockId;output=$_.output;wrapperSummarySha256=if(Test-Path ($_.output+'.wrapper-summary.json')){Get-G13R36LowerSha256 ($_.output+'.wrapper-summary.json')}else{$null}}});passed=$failed.Count-eq0};$ledger.Add($entry);if($failed.Count){throw "Wave $Wave failed: $($failed-join'; ')"}}
try{
 Write-Checkpoint 'authorized-preflight-passed' 0 ''
 $warmups=@($plan.warmup.blocks);for($w=1;$w-le2;$w++){Invoke-Wave $w @($warmups[(($w-1)*4)..(($w*4)-1)]) 'warmup';$completedWarmup+=4;Write-Checkpoint 'warmup-wave-completed' $w ''}
 Start-Sleep -Seconds ([int]$plan.warmup.quietStabilizationSeconds);$measuredStarted=[DateTimeOffset]::Now
 foreach($wave in 1..96){$items=@($scheduleDoc.rows|Where-Object wave -eq $wave|Sort-Object lane);if($items.Count-ne4){throw "Measured wave $wave cardinality is $($items.Count)."};Invoke-Wave $wave $items 'measured';$completedMeasured+=4;Write-Checkpoint 'measured-wave-completed' $wave ''}
 $measuredCompleted=[DateTimeOffset]::Now;Write-Checkpoint 'pilot-execution-completed-awaiting-analysis' 96 ''
 $manifest=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-four-lane-nonformal-pilot-execution-manifest-v10';completedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-G13R36LowerSha256 $PilotPlanPath;scheduleSha256=Get-G13R36LowerSha256 $SchedulePath;provenanceSha256=Get-G13R36LowerSha256 $ProvenancePath;warmupBlockCount=$completedWarmup;measuredBlockCount=$completedMeasured;measuredSampleCount=1152;measuredStartedAt=$measuredStarted.ToString('o');measuredCompletedAt=$measuredCompleted.ToString('o');measuredElapsedSeconds=($measuredCompleted-$measuredStarted).TotalSeconds;waveLedger=$ledger.ToArray();formalCampaign=$false;excludedFromFormalAnalysis=$true;automaticRetryAttempted=$false;automaticResumeAttempted=$false;completed=$true};Write-G13R36CreateNewUtf8NoBomJson -Path (Join-Path $pilotRoot 'execution-manifest.json') -Value $manifest -Depth 35;Write-Host 'Gate13R 36h NON-FORMAL concurrency pilot execution completed; analysis remains.' -ForegroundColor Green;exit 0
}catch{
 $errorText=$_.Exception.ToString();try{Write-Checkpoint 'failed-no-auto-retry-no-resume' $(if($completedMeasured){[math]::Ceiling($completedMeasured/4)}else{0}) $errorText}catch{}
 $files=@(Get-ChildItem -LiteralPath $pilotRoot -Recurse -File -Force|Where-Object{$_.Name-notlike'partial-output-manifest*'});$partial=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-four-lane-pilot-partial-output-manifest-v10';createdAtUtc=[DateTime]::UtcNow.ToString('o');completedWarmupBlocks=$completedWarmup;completedMeasuredBlocks=$completedMeasured;fileCount=$files.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);files=@($files|ForEach-Object{[pscustomobject]@{relativePath=$_.FullName.Substring($pilotRoot.Length+1).Replace('\','/');bytes=[long]$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}});formalCampaign=$false;eligibleForFormalAnalysis=$false};try{Write-G13R36AtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'partial-output-manifest.json') -Value $partial -Depth 20}catch{};$failure=[ordered]@{schemaVersion=1;failureKind='gate13r-36h-four-lane-nonformal-pilot-failure-v10';failedAtUtc=[DateTime]::UtcNow.ToString('o');error=$errorText;completedWarmupBlocks=$completedWarmup;completedMeasuredBlocks=$completedMeasured;status='FAILED-NO-AUTO-RETRY-NO-RESUME-NO-MERGE';formalCampaign=$false;formalExecutionAuthorized=$false};try{Write-G13R36AtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'failure-receipt.json') -Value $failure -Depth 15}catch{};Write-Error "Gate13R 36h pilot failed closed: $errorText";exit 1
}
